const toSlug = (s) =>
  String(s ?? '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[“”"’']/g, '')
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');

const pad2 = (n) => String(Number(n || 1)).padStart(2, '0');

function stripCodeFences(s) {
  return String(s ?? '')
    .replace(/^\s*```(?:json|typescript|ts|javascript|js)?\s*/i, '')
    .replace(/\s*```$/,'')
    .trim();
}
function escapeRegExp(s){ return String(s ?? '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

function coalesce(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null) {
      const sv = typeof v === 'string' ? v : (typeof v === 'object' ? JSON.stringify(v) : String(v));
      if (String(sv).trim() !== '') return v;
