// ---------- extractor robusto de JSON incrustado ----------
function extractJsonEnvelope(big) {
  const s = String(big ?? '');
  // Intento 1: string completo es JSON
  try {
    const obj = JSON.parse(s);
    if (obj && typeof obj === 'object' && (obj.fileContent || obj.content || obj.text || obj.code)) {
      return {
        fileName: obj.fileName || obj.filename || undefined,
        fileContent: String(obj.fileContent ?? obj.content ?? obj.text ?? obj.code ?? ''),
      };
    }
  } catch {}

  // Intento 2: buscar bloque con "fileContent"
  const idxFirstBrace = s.indexOf('{');
  const idxLastBrace  = s.lastIndexOf('}');
  if (idxFirstBrace !== -1 && idxLastBrace !== -1 && idxLastBrace > idxFirstBrace) {
    const window = s.slice(idxFirstBrace, idxLastBrace + 1);
    const candidates = [];
    const re = /\{[\s\S]*?"fileContent"\s*:\s*("[\s\S]*?"|null|true|false|\d+|\{[\s\S]*?\}|\[[\s\S]*?\])[\s\S]*?\}/g;
    let m;
    while ((m = re.exec(window)) !== null) candidates.push(m[0]);
    for (let i = candidates.length - 1; i >= 0; i--) {
      try {
        const obj = JSON.parse(candidates[i]);
        if (obj && typeof obj === 'object' && (obj.fileContent || obj.content || obj.text || obj.code)) {
          return {
            fileName: obj.fileName || obj.filename || undefined,
            fileContent: String(obj.fileContent ?? obj.content ?? obj.text ?? obj.code ?? ''),
          };
        }
      } catch {}
    }
  }
  return null;
}

