  // D) Aserciones genéricas con locator('ref=eXX') -> reemplazar por PRODUCT STORE visible
  code = code.replace(
    /await\s+expect\(\s*page\.locator\(\s*['"`]ref=e\d+['"`]\s*\)\s*\)\.toBeVisible\(\)\s*;?/gi,
    `await expect(page.getByRole('link', { name: 'PRODUCT STORE' })).toBeVisible();`
  );

  // E) Cualquier uso residual de locator('ref=eXX') -> convertir a Home para no romper
  code = code.replace(
    /page\.locator\(\s*['"`]ref=e\d+['"`]\s*\)/gi,
    `page.getByRole('link', { name: '${navTarget}', exact: true })`
  );

  // F) Selectores por atributo: a[ref="e13"] / link[ref="e13"]
  const attrToRole = {
    e10: 'Home',
    e13: 'Contact',
    e15: 'About us',
    e17: 'Cart',
    e19: 'Log in',
    e21: 'Sign up',
  };
  code = code.replace(/page\.locator\(\s*['"`](?:a|link)\[ref=["']e(\d+)["']\]['"`]\s*\)\.click\(\)\s*;?/gi, (m, num) => {
    const name = attrToRole[`e${num}`] || navTarget;
    return `page.getByRole('link', { name: '${name}', exact: true }).click();`;
  });
  code = code.replace(/page\.locator\(\s*['"`](?:a|link)\[ref=["']e(\d+)["']\]['"`]\s*\)/gi, (m, num) => {
    const name = attrToRole[`e${num}`] || navTarget;
    return `page.getByRole('link', { name: '${name}', exact: true })`;
  });

  // G) EXPECTS con a[ref="e.."] -> reemplazar por el rol equivalente
  code = code.replace(
    /await\s+expect\(\s*page\.locator\(\s*['"`](?:a|link)\[ref=["']e(\d+)["']\]['"`]\s*\)\s*\)\.toBeVisible\(\)\s*;?/gi,
    (m, num) => {
      const name = attrToRole[`e${num}`] || 'Home';
      return `await expect(page.getByRole('link', { name: '${name}' })).toBeVisible();`;
    }
  );

  return code;
}

